#include <stdlib.h>

static int cmp_desc(const void *a, const void *b) {
    long long va = *(const long long *)a;
    long long vb = *(const long long *)b;
    if (va < vb) return 1;
    if (va > vb) return -1;
    return 0;
}

static int cmp_asc(const void *a, const void *b) {
    long long va = *(const long long *)a;
    long long vb = *(const long long *)b;
    if (va > vb) return 1;
    if (va < vb) return -1;
    return 0;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    long long *t = (long long *)malloc(n * sizeof(long long));
    for (int i = 0; i < n; i++) {
        scanf("%lld", &t[i]);
    }

    long long *f = (long long *)malloc(m * sizeof(long long));
    for (int j = 0; j < m; j++) {
        scanf("%lld", &f[j]);
    }

    // Binary search for the cutoff value X
    long long low = 0, high = 100000000000000LL; // 10^14 is safe
    long long x = high;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        long long count = 0;
        for (int j = 0; j < m; j++) {
            count += (mid / f[j]) + 1;
            if (count >= n) break;
        }
        if (count >= n) {
            x = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }

    // Collect elements strictly less than X
    long long *slots = (long long *)malloc(n * sizeof(long long));
    int slot_count = 0;

    for (int j = 0; j < m; j++) {
        if (x > 0) {
            long long max_c = (x - 1) / f[j];
            for (long long c = 0; c <= max_c; c++) {
                if (slot_count < n) {
                    slots[slot_count++] = c * f[j];
                }
            }
        }
    }

    // Fill the remaining slots with X
    while (slot_count < n) {
        slots[slot_count++] = x;
    }

    qsort(slots, n, sizeof(long long), cmp_asc);
    qsort(t, n, sizeof(long long), cmp_desc);

    unsigned long long total_wait = 0;
    for (int i = 0; i < n; i++) {
        total_wait += (unsigned long long)t[i] * slots[i];
    }

    printf("%llu\n", total_wait);

    free(t);
    free(f);
    free(slots);

    return 0;
}
