#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long val;
    int step;
} Node;

static int cmp_desc(const void *a, const void *b) {
    int va = *(const int *)a;
    int vb = *(const int *)b;
    if (va < vb) return 1;
    if (va > vb) return -1;
    return 0;
}

static void min_heapify(Node *heap, int n, int i) {
    while (1) {
        int smallest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < n && heap[left].val < heap[smallest].val)
            smallest = left;
        if (right < n && heap[right].val < heap[smallest].val)
            smallest = right;

        if (smallest != i) {
            Node temp = heap[i];
            heap[i] = heap[smallest];
            heap[smallest] = temp;
            i = smallest;
        } else {
            break;
        }
    }
}

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int *t = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &t[i]);
    }

    int *f = (int *)malloc(m * sizeof(int));
    for (int j = 0; j < m; j++) {
        scanf("%d", &f[j]);
    }

    if (m >= n) {
        printf("0\n");
        free(t);
        free(f);
        return 0;
    }

    qsort(t, n, sizeof(int), cmp_desc);

    Node *heap = (Node *)malloc(m * sizeof(Node));
    for (int j = 0; j < m; j++) {
        heap[j].val = f[j];
        heap[j].step = f[j];
    }

    for (int i = m / 2 - 1; i >= 0; i--) {
        min_heapify(heap, m, i);
    }

    long long total_wait = 0;
    for (int i = m; i < n; i++) {
        total_wait += heap[0].val * (long long)t[i];
        heap[0].val += heap[0].step;
        min_heapify(heap, m, 0);
    }

    printf("%lld\n", total_wait);

    free(t);
    free(f);
    free(heap);
    return 0;
}
